<script setup lang="ts">import {Head,useForm} from '@inertiajs/vue3';import PageHeader from '@/Components/Shared/PageHeader.vue';import {Button} from '@/components/ui/button';import {Input} from '@/components/ui/input';const p=defineProps<{campaign:any|null,advertisers:any[],placements:any[]}>();const f=useForm({advertiser_id:p.campaign?.advertiser_id??'',name:p.campaign?.name??'',objective:p.campaign?.objective??'awareness',pricing_model:p.campaign?.pricing_model??'flat',budget_cents:p.campaign?.budget_cents??0,contract_value_cents:p.campaign?.contract_value_cents??0,impression_goal:p.campaign?.impression_goal??null,click_goal:p.campaign?.click_goal??null,starts_at:p.campaign?.starts_at?.slice(0,16)??'',ends_at:p.campaign?.ends_at?.slice(0,16)??'',internal_notes:p.campaign?.internal_notes??'',placement_ids:p.campaign?.placements?.map((x:any)=>x.id)??[]});const save=()=>p.campaign?f.put(`/admin/ad-campaigns/${p.campaign.id}`):f.post('/admin/ad-campaigns');</script><template><Head title="Advertising Campaign"/><form class="space-y-6 p-6" @submit.prevent="save"><PageHeader :title="campaign?'Edit Advertising Campaign':'Create Advertising Campaign'" description="Campaign terms, goals, schedule, and eligible inventory."/><div class="grid gap-4 rounded-xl border p-5 md:grid-cols-2"><label>Advertiser<select v-model="f.advertiser_id" class="h-10 w-full rounded-md border bg-background px-3"><option value="">Select advertiser</option><option v-for="a in advertisers" :value="a.id">{{a.name}}</option></select></label><label>Campaign name<Input v-model="f.name"/></label><label>Objective<select v-model="f.objective" class="h-10 w-full rounded-md border bg-background px-3"><option>awareness</option><option>traffic</option><option>conversion</option><option>sponsorship</option></select></label><label>Pricing model<select v-model="f.pricing_model" class="h-10 w-full rounded-md border bg-background px-3"><option>flat</option><option>cpm</option><option>cpc</option><option>sponsorship</option></select></label><label>Budget (cents)<Input v-model="f.budget_cents" type="number"/></label><label>Contract value (cents)<Input v-model="f.contract_value_cents" type="number"/></label><label>Impression goal<Input v-model="f.impression_goal" type="number"/></label><label>Click goal<Input v-model="f.click_goal" type="number"/></label><label>Starts<Input v-model="f.starts_at" type="datetime-local"/></label><label>Ends<Input v-model="f.ends_at" type="datetime-local"/></label><fieldset class="md:col-span-2"><legend class="mb-2 font-medium">Placements</legend><div class="grid gap-2 md:grid-cols-3"><label v-for="x in placements" class="flex gap-2 rounded-md border p-3"><input v-model="f.placement_ids" type="checkbox" :value="x.id"/>{{x.name}}</label></div></fieldset><label class="md:col-span-2">Internal notes<textarea v-model="f.internal_notes" class="min-h-24 w-full rounded-md border bg-background p-3"/></label></div><Button :disabled="f.processing">Save Campaign</Button></form></template>